/**
 * Escapes special characters in a string so that it can be safely used as a literal
 * within a regular expression pattern.
 *
 * @param str - The input string to escape.
 * @returns A new string with special characters escaped.
 */
export const escapeRegex = (str: string): string => {
  return str.replace(/[/\-\\^$*+?.()|[\]{}]/g, '\\$&');
};

type SanitizeUserMentionParams = {
  text: string;
  userMentionCssClassName: string;
  mentionedUserStyles: string;
};

/**
 * `<span class="mentioned-user-container-class">\@JohnDoe</span> how are you?`
 *
 * We replace the referential class to the one generated by styletron, using the variable `mentionedUserStyles`.
 * The resulting message will with the specified class.
 *
 * `<span class="custom-class">\@JohnDoe</span> how are you?`
 */
export const sanitizeClassUserMention = ({
  text,
  userMentionCssClassName,
  mentionedUserStyles,
}: SanitizeUserMentionParams): string =>
  text.replace(new RegExp(userMentionCssClassName, 'g'), mentionedUserStyles);
